CREATE TABLE "DriveSyncJob" ("id" TEXT NOT NULL, "mode" TEXT NOT NULL, "storeId" TEXT NOT NULL, "week" TEXT NOT NULL, "planVersion" INTEGER NOT NULL, "status" TEXT NOT NULL, "proposals" JSONB NOT NULL, "total" INTEGER NOT NULL DEFAULT 0, "processed" INTEGER NOT NULL DEFAULT 0, "success" INTEGER NOT NULL DEFAULT 0, "failures" TEXT[] NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DriveSyncJob_pkey" PRIMARY KEY ("id"));
